public with sharing class ContactTriggerHandler {

    public void onBeforeInsertUpdate(List<Contact> newContacts, Map<Id, Contact> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // 1 SOQL: fetch BillingCountry and AccountSource for all referenced accounts
        Map<Id, Account> accountMap = new Map<Id, Account>([
            SELECT Id, BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Contact c : newContacts) {
            if (c.AccountId == null || !accountMap.containsKey(c.AccountId)) {
                continue;
            }
            Account a = accountMap.get(c.AccountId);

            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }

            boolean isInsert = (c.Id == null) || !oldMap.containsKey(c.Id);
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    public void onAfterInsert(List<Contact> newContacts) {
        // Preserve trigger order: first contact with a phone per account wins
        Map<Id, Contact> firstContactWithPhoneByAccount = new Map<Id, Contact>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                if (!firstContactWithPhoneByAccount.containsKey(c.AccountId)) {
                    firstContactWithPhoneByAccount.put(c.AccountId, c);
                }
            }
        }

        if (firstContactWithPhoneByAccount.isEmpty()) {
            return;
        }

        // 1 SOQL: check current account phones
        List<Account> accounts = [
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :firstContactWithPhoneByAccount.keySet()
        ];

        List<Account> accountsToUpdate = new List<Account>();
        for (Account a : accounts) {
            Contact firstContact = firstContactWithPhoneByAccount.get(a.Id);
            if (String.isBlank(a.Phone) && firstContact != null && String.isNotBlank(firstContact.Phone)) {
                accountsToUpdate.add(new Account(Id = a.Id, Phone = firstContact.Phone));
            }
        }

        // 1 DML: bulk update accounts that still have no phone
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
