public with sharing class ContactDomainService {

    /**
     * Groups contacts by the lower-cased domain part of their email address.
     *
     * @param accountIds Set of Account Ids to filter contacts. Null or empty returns empty map.
     * @return Map where key is lower-cased email domain (e.g. 'example.com') and value is list of Contacts
     *         with Id, Email, and AccountId populated. Contacts without an email are excluded.
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> result = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Query contacts with required fields, respecting sharing via 'with sharing' on class
        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
              AND Email != ''
        ];

        for (Contact c : contacts) {
            String email = c.Email.trim();
            if (String.isBlank(email)) {
                continue;
            }

            Integer atIdx = email.lastIndexOf('@');
            if (atIdx == -1 || atIdx == email.length() - 1) {
                // Invalid email format, no domain part
                continue;
            }

            String domain = email.substring(atIdx + 1).toLowerCase();

            if (!result.containsKey(domain)) {
                result.put(domain, new List<Contact>());
            }
            result.get(domain).add(c);
        }

        return result;
    }
}
