public class PaymentTerms {

    private static final Integer MAX_NET_DAYS = 180;
    private static final Pattern NET_PATTERN = Pattern.compile('(?i)^NET\\s*(\\d{1,3})$');
    private static final String DUE_ON_RECEIPT = 'DUE ON RECEIPT';

    /**
     * Parses payment terms string and returns net days.
     * @param terms Payment terms string (e.g., "NET 30", "net30", "DUE ON RECEIPT")
     * @return Number of net days as Integer
     * @throws UnsupportedTermsException if terms format is not recognized
     * @throws TermsOutOfRangeException if net days exceeds 180
     */
    public static Integer parseNetDays(String terms) {
        String originalTerms = terms;

        if (terms == null) {
            throw new UnsupportedTermsException('Unsupported payment terms: null');
        }

        String normalized = terms.trim().toUpperCase();

        if (normalized.isEmpty()) {
            throw new UnsupportedTermsException('Unsupported payment terms: ' + originalTerms);
        }

        // Check for DUE ON RECEIPT (case insensitive, whitespace normalized)
        if (normalized.replaceAll('\\s+', ' ') == DUE_ON_RECEIPT) {
            return 0;
        }

        // Check for NET pattern
        Matcher matcher = NET_PATTERN.matcher(normalized);
        if (matcher.matches()) {
            Integer netDays = Integer.valueOf(matcher.group(1));
            if (netDays > MAX_NET_DAYS) {
                throw new TermsOutOfRangeException('Net days out of range: ' + netDays);
            }
            return netDays;
        }

        throw new UnsupportedTermsException('Unsupported payment terms: ' + originalTerms);
    }

    /**
     * Calculates due date from invoice date and payment terms.
     * @param invoiceDate Invoice date
     * @param terms Payment terms string
     * @return Due date as Date
     * @throws UnsupportedTermsException if terms format is not recognized
     * @throws TermsOutOfRangeException if net days exceeds 180
     */
    public static Date dueDate(Date invoiceDate, String terms) {
        Integer netDays = parseNetDays(terms);
        return invoiceDate.addDays(netDays);
    }
}
