public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ---------- 1. Basic argument validation ----------
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200');
        }
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields list cannot be null or empty');
        }

        // ---------- 2. Resolve object (case-insensitive) ----------
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        String normalizedObjectName = null;
        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                normalizedObjectName = key;
                break;
            }
        }
        if (normalizedObjectName == null) {
            throw new SearchException('Object ' + objectApiName + ' does not exist');
        }

        Schema.SObjectType objType = globalDescribe.get(normalizedObjectName);
        Schema.DescribeSObjectResult objDescribe = objType.getDescribe();

        // ---------- 3. Object-level read access ----------
        if (!objDescribe.isAccessible()) {
            throw new SearchException('Current user cannot read object ' + normalizedObjectName);
        }

        // ---------- 4. Field describe map (lower-case key -> correct-case name) ----------
        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();
        Map<String, String> lowerToCorrectCase = new Map<String, String>();
        for (String fname : fieldMap.keySet()) {
            lowerToCorrectCase.put(fname.toLowerCase(), fname);
        }

        // ---------- 5. Validate requested SELECT fields ----------
        Set<String> selectFields = new Set<String>{'Id'}; // Id always included
        for (String f : fields) {
            String lc = f.toLowerCase();
            String correct = lowerToCorrectCase.get(lc);
            if (correct == null) {
                throw new SearchException('Field ' + f + ' not found on ' + normalizedObjectName);
            }
            Schema.DescribeFieldResult fd = fieldMap.get(correct).getDescribe();
            if (!fd.isAccessible()) {
                throw new SearchException('Field ' + correct + ' is not readable');
            }
            selectFields.add(correct);
        }

        // ---------- 6. Validate filter keys ----------
        Map<String, Object> safeFilters = new Map<String, Object>();
        if (filters != null) {
            for (String fkey : filters.keySet()) {
                String lc = fkey.toLowerCase();
                String correct = lowerToCorrectCase.get(lc);
                if (correct == null) {
                    throw new SearchException('Filter field ' + fkey + ' not found on ' + normalizedObjectName);
                }
                Schema.DescribeFieldResult fd = fieldMap.get(correct).getDescribe();
                if (!fd.isFilterable()) {
                    throw new SearchException('Field ' + correct + ' cannot be filtered');
                }
                if (!fd.isAccessible()) {
                    throw new SearchException('Filter field ' + correct + ' is not readable');
                }
                safeFilters.put(correct, filters.get(fkey));
            }
        }

        // ---------- 7. Validate ORDER BY field ----------
        String orderByCorrect = null;
        if (orderByField != null && !orderByField.trim().isEmpty()) {
            String lc = orderByField.trim().toLowerCase();
            orderByCorrect = lowerToCorrectCase.get(lc);
            if (orderByCorrect == null) {
                throw new SearchException('Order-by field ' + orderByField + ' not found on ' + normalizedObjectName);
            }
            Schema.DescribeFieldResult fd = fieldMap.get(orderByCorrect).getDescribe();
            if (!fd.isSortable()) {
                throw new SearchException('Field ' + orderByCorrect + ' cannot be sorted');
            }
            if (!fd.isAccessible()) {
                throw new SearchException('Order-by field ' + orderByCorrect + ' is not readable');
            }
        }

        // ---------- 8. Build dynamic SOQL ----------
        String selectClause = String.join(new List<String>(selectFields), ', ');
        String whereClause = '';
        Map<String, Object> bindMap = new Map<String, Object>();
        Integer bindIdx = 0;

        if (!safeFilters.isEmpty()) {
            List<String> conditions = new List<String>();
            for (String fname : safeFilters.keySet()) {
                String bindName = 'f' + bindIdx++;
                conditions.add(fname + ' = :' + bindName);
                bindMap.put(bindName, safeFilters.get(fname));
            }
            whereClause = ' WHERE ' + String.join(conditions, ' AND ');
        }

        String orderByClause = (orderByCorrect != null) ? ' ORDER BY ' + orderByCorrect + ' ASC' : '';
        String limitClause = ' LIMIT :maxRowsBind';
        bindMap.put('maxRowsBind', maxRows);

        String soql = 'SELECT ' + selectClause + ' FROM ' + normalizedObjectName +
                      whereClause + orderByClause + limitClause;

        // ---------- 9. Execute with bind variables ----------
        List<SObject> results;
        try {
            results = Database.queryWithBinds(soql, bindMap);
        } catch (QueryException e) {
            // Should not happen if validation is correct, but wrap just in case
            throw new SearchException('Query execution failed: ' + e.getMessage());
        }

        return results;
    }
}
