public with sharing class ContactLookupAction {

    @InvocableMethod(label='Find Contact by Email' description='Finds a contact by email address')
    public static List<Result> find(List<Request> requests) {
        // Normalize all input emails: trim, lowercase, ignore blanks
        Set<String> normalizedEmails = new Set<String>();
        for (Request req : requests) {
            if (req.email != null) {
                String normalized = req.email.trim().toLowerCase();
                if (!normalized.isEmpty()) {
                    normalizedEmails.add(normalized);
                }
            }
        }

        // One SOQL query: get the earliest-created contact per email
        Map<String, Id> emailToContactId = new Map<String, Id>();
        if (!normalizedEmails.isEmpty()) {
            List<Contact> contacts = [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE LOWER(Email) IN :normalizedEmails
                ORDER BY Email, CreatedDate ASC
            ];
            for (Contact c : contacts) {
                String key = c.Email.toLowerCase();
                if (!emailToContactId.containsKey(key)) {
                    emailToContactId.put(key, c.Id);
                }
            }
        }

        // Build results in the same order as the requests
        List<Result> results = new List<Result>();
        for (Request req : requests) {
            Result res = new Result();
            if (req.email != null) {
                String normalized = req.email.trim().toLowerCase();
                if (!normalized.isEmpty() && emailToContactId.containsKey(normalized)) {
                    res.contactId = emailToContactId.get(normalized);
                    res.found = true;
                } else {
                    res.contactId = null;
                    res.found = false;
                }
            } else {
                res.contactId = null;
                res.found = false;
            }
            results.add(res);
        }
        return results;
    }

    public class Request {
        @InvocableVariable(label='Email' description='Email address to search for' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact ID' description='ID of the found contact')
        public Id contactId;

        @InvocableVariable(label='Found' description='Whether a contact was found')
        public Boolean found;
    }
}
