    public static Integer publishShipments(List<Shipment> shipments) {
        if (shipments == null || shipments.isEmpty()) {
            return 0;
        }

        List<FB_Shipment_Event__e> eventsToPublish = new List<FB_Shipment_Event__e>();

        for (Shipment shipment : shipments) {
            if (shipment.orderNumber != null && !shipment.orderNumber.trim().isEmpty()) {
                FB_Shipment_Event__e evt = new FB_Shipment_Event__e();
                evt.Order_Number__c = shipment.orderNumber.trim();
                evt.Tracking_Number__c = shipment.trackingNumber;
                evt.Carrier__c = shipment.carrier;
                eventsToPublish.add(evt);
            }
        }

        if (eventsToPublish.isEmpty()) {
            return 0;
        }

        List<Database.SaveResult> results = EventBus.publish(eventsToPublish);

        Integer successCount = 0;
        for (Database.SaveResult result : results) {
            if (result.isSuccess()) {
                successCount++;
            }
        }
        return successCount;
    }
}
