public class OpportunityPipelineHandler {

    // Prevents re-entry when AccountTrigger updates opportunities after we update accounts.
    private static Boolean isRunning = false;

    /**
     * Entry point from OpportunityTrigger.
     * Computes the set of affected Account IDs and recalculates their roll-ups.
     */
    public static void handleTrigger(
        List<Opportunity> newList,
        Map<Id, Opportunity> newMap,
        List<Opportunity> oldList,
        Map<Id, Opportunity> oldMap,
        System.TriggerOperation operation
    ) {
        if (isRunning) {
            return;
        }
        isRunning = true;

        try {
            Set<Id> accountIds = new Set<Id>();

            switch on operation {
                when AFTER_INSERT {
                    for (Opportunity opp : newList) {
                        if (!opp.IsClosed) {
                            accountIds.add(opp.AccountId);
                        }
                    }
                    break;

                when AFTER_UPDATE {
                    for (Integer i = 0; i < newList.size(); i++) {
                        Opportunity newOpp = newList[i];
                        Opportunity oldOpp = oldList[i];

                        // Only react to changes that affect the open pipeline roll-up.
                        if (oldOpp.Amount != newOpp.Amount
                            || oldOpp.IsClosed != newOpp.IsClosed
                            || oldOpp.AccountId != newOpp.AccountId) {

                            if (!oldOpp.IsClosed) {
                                accountIds.add(oldOpp.AccountId);
                            }
                            if (!newOpp.IsClosed) {
                                accountIds.add(newOpp.AccountId);
                            }
                        }
                    }
                    break;

                when AFTER_DELETE {
                    for (Opportunity opp : oldList) {
                        if (!opp.IsClosed) {
                            accountIds.add(opp.AccountId);
                        }
                    }
                    break;

                when AFTER_UNDELETE {
                    for (Opportunity opp : newList) {
                        if (!opp.IsClosed) {
                            accountIds.add(opp.AccountId);
                        }
                    }
                    break;
            }

            if (!accountIds.isEmpty()) {
                recalculateAccounts(accountIds);
            }
        } finally {
            isRunning = false;
        }
    }

    /**
     * Aggregates open opportunities per account and updates the two roll-up fields.
     * Accounts with no open opportunities are set to 0 (not null).
     */
    private static void recalculateAccounts(Set<Id> accountIds) {
        accountIds.remove(null);
        if (accountIds.isEmpty()) {
            return;
        }

        // Single aggregate query for all affected accounts.
        List<AggregateResult> results = [
            SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) oppCount
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ];

        // Start every account at 0 so accounts that lose their last open opp show 0, not blank.
        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Id accId : accountIds) {
            accountsToUpdate.put(accId, new Account(
                Id = accId,
                FB_Open_Pipeline__c = 0,
                FB_Open_Opportunities__c = 0
            ));
        }

        // Overlay actual aggregates where they exist.
        for (AggregateResult ar : results) {
            Id accId = (Id) ar.get('AccountId');
            Decimal totalAmount = (Decimal) ar.get('totalAmount');
            Integer oppCount = (Integer) ar.get('oppCount');

            Account acc = accountsToUpdate.get(accId);
            if (acc != null) {
                acc.FB_Open_Pipeline__c = (totalAmount != null) ? totalAmount : 0;
                acc.FB_Open_Opportunities__c = (oppCount != null) ? oppCount : 0;
            }
        }

        // One DML for all accounts.
        update accountsToUpdate.values();
    }
}
