public with sharing class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
        // No-argument constructor as required
    }

    public void execute(SchedulableContext ctx) {
        purgeOldLogs();
    }

    public static Id scheduleNightly() {
        String cronExpression = '0 0 2 * * ?'; // Every day at 02:00
        String jobName = 'Log purge (nightly)';
        return System.schedule(jobName, cronExpression, new LogPurgeJob());
    }

    private void purgeOldLogs() {
        DateTime thirtyDaysAgo = DateTime.now().addDays(-30);
        DateTime oneEightyDaysAgo = DateTime.now().addDays(-180);

        // Query logs to delete:
        // - Non-ERROR logs older than 30 days
        // - ERROR logs older than 180 days
        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (
                (Level__c != 'ERROR' AND CreatedDate < :thirtyDaysAgo)
                OR
                (Level__c = 'ERROR' AND CreatedDate < :oneEightyDaysAgo)
            )
            LIMIT 10000
        ];

        if (!logsToDelete.isEmpty()) {
            Database.delete(logsToDelete, false);
        }
    }
}
