public with sharing class OpportunityRollupService {

    /**
     * Returns a map of Account Id to the total won Amount for the current calendar year.
     * Only the requested accountIds are keys; missing or blank amounts become 0.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        // Guard clause for null or empty input
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Current calendar year
        Integer currentYear = Date.today().year();

        // Aggregate query: sum Amount grouped by AccountId
        List<AggregateResult> aggregates = [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsWon = true
              AND CALENDAR_YEAR(CloseDate) = :currentYear
            GROUP BY AccountId
        ];

        // Initialize all requested accounts to 0
        for (Id accId : accountIds) {
            result.put(accId, 0);
        }

        // Populate from aggregate results
        for (AggregateResult ar : aggregates) {
            Id accId = (Id) ar.get('AccountId');
            Decimal sum = (Decimal) ar.get('totalAmount');
            result.put(accId, sum != null ? sum : 0);
        }

        return result;
    }
}
