public class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities((List<Opportunity>) records);
        }
    }

    protected override void onBeforeInsert(List<SObject> records) {
        validateAmountNotNegative((List<Opportunity>) records);
    }

    protected override void onBeforeUpdate(Map<Id, SObject> oldMap, List<SObject> newRecords) {
        List<Opportunity> newOpps = (List<Opportunity>) newRecords;
        Map<Id, Opportunity> oldOpps = (Map<Id, Opportunity>) oldMap;
        validateAmountNotNegative(newOpps);
        validateAmountNotChangedOnWon(oldOpps, newOpps);
    }

    private void validateAmountNotNegative(List<Opportunity> opportunities) {
        for (Opportunity opp : opportunities) {
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    private void validateAmountNotChangedOnWon(Map<Id, Opportunity> oldMap, List<Opportunity> newOpportunities) {
        for (Opportunity newOpp : newOpportunities) {
            Opportunity oldOpp = oldMap.get(newOpp.Id);
            if (oldOpp != null && oldOpp.StageName == 'Closed Won' && newOpp.Amount != oldOpp.Amount) {
                error('Amount cannot change on a won opportunity.', newOpp, Opportunity.Amount);
            }
        }
    }
}
