```apex
public with sharing class ContactPhoneCleanup {

    /**
     * Normalizes Phone numbers on the given contacts by stripping every character
     * except digits and a leading plus sign. Performs a single partial-save update
     * so that validation failures on one record don't block the others.
     *
     * @param contactIds  Up to 200 Contact Ids (bulk-safe).
     * @return Map of Contact Id → first error message for contacts that failed to save.
     *         Empty map when all succeed.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failures;
        }

        // Query only the fields we need; limit is implicit via the IN clause (max 200 ids).
        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
        ];

        // Regex: keep only digits (0-9) and plus (+). Replace everything else with ''.
        Pattern phonePattern = Pattern.compile('[^0-9+]');

        List<Contact> toUpdate = new List<Contact>();
        for (Contact c : contacts) {
            if (c.Phone != null) {
                String cleaned = phonePattern.matcher(c.Phone).replaceAll('');
                // Only add to update list if the value actually changes (avoids unnecessary DML).
                if (!cleaned.equals(c.Phone)) {
                    c.Phone = cleaned;
                    toUpdate.add(c);
                }
            }
        }

        if (toUpdate.isEmpty()) {
            return failures; // Nothing to do.
        }

        // Partial save: false = allow other records to succeed even if one fails.
        List<Database.SaveResult> results = Database.update(toUpdate, false);

        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult sr = results[i];
            if (!sr.isSuccess()) {
                // Capture the first error message only, per requirements.
                String firstError = sr.getErrors()[0].getMessage();
                failures.put(toUpdate[i].Id, firstError);
            }
        }

        return failures;
    }
}
