public with sharing class PipelineSummary {

    /**
     * Returns a map of the four open pipeline stages to the sum of Amount for opportunities
     * whose CloseDate falls within [fromDate, toDate] (inclusive).
     *
     * Stages without matching opportunities return 0, never null.
     * Opportunities with a null Amount contribute 0 to the sum.
     *
     * @param fromDate inclusive lower bound on CloseDate
     * @param toDate   inclusive upper bound on CloseDate
     * @return Map with exactly four keys:
     *         Prospecting, Qualification, Proposal/Price Quote, Negotiation/Review
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        // Fixed, small set of stages managed by Sales Ops. Four aggregate queries is
        // simpler and more readable than a single GROUP BY that then needs post-processing
        // to guarantee all four keys exist with 0 instead of null.
        List<String> stages = new List<String>{
            'Prospecting',
            'Qualification',
            'Proposal/Price Quote',
            'Negotiation/Review'
        };

        Map<String, Decimal> result = new Map<String, Decimal>();

        for (String stage : stages) {
            // Aggregate query per stage – one row, one column, constant cost regardless of data volume.
            List<AggregateResult> agg = [
                SELECT COALESCE(SUM(Amount), 0)
                FROM Opportunity
                WHERE StageName = :stage
                  AND CloseDate >= :fromDate
                  AND CloseDate <= :toDate
            ];

            Decimal sum = (Decimal) agg[0].get('expr0');
            result.put(stage, sum == null ? 0 : sum);
        }

        return result;
    }
}
