public class ErpCustomerSync implements Queueable, Database.AllowsCallouts {
    private final List<Id> accountIds;

    public ErpCustomerSync(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    public void execute(QueueableContext context) {
        List<Account> accounts = [
            SELECT Id, Name, BillingCountry
            FROM Account
            WHERE Id IN :accountIds
        ];

        for (Account acc : accounts) {
            sendToErp(acc);
        }
    }

    private void sendToErp(Account acc) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setTimeout(120000);

        // ERP expects a JSON array of 1–200 customers; we send one per request
        // so the ERP team can trace each account independently.
        Map<String, Object> customer = new Map<String, Object>{
            'salesforceId' => acc.Id,
            'name'         => acc.Name,
            'country'      => acc.BillingCountry
        };
        req.setBody(JSON.serialize(new List<Object>{ customer }));

        Http http = new Http();
        HttpResponse res = http.send(req);
        // ERP returns 202 Accepted; error handling and retries are out of scope.
    }
}
