public with sharing class FollowUpTaskService {

    /**
     * Creates a follow-up Task for each supplied Opportunity.
     *
     * Each Task is inserted in its own transaction via try/catch so that
     * validation-rule failures (or any other DmlException) on one record
     * do not prevent the others from being created.
     *
     * @param opportunityIds  Ids of the Opportunities that need a follow-up task
     * @return                Set of Opportunity Ids whose task could NOT be created;
     *                        empty set when every task succeeded
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // Bulk-query the fields we need so we only hit the database once.
        List<Opportunity> opportunities = [
            SELECT Id, Name, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        Date dueDate = Date.today().addDays(7);

        for (Opportunity opp : opportunities) {
            Task followUp = new Task(
                WhatId      = opp.Id,
                OwnerId     = opp.OwnerId,
                Subject     = 'Follow up: ' + opp.Name,
                ActivityDate= dueDate,
                Status      = 'Not Started',
                Priority    = 'Normal'
            );

            try {
                insert followUp;
            } catch (DmlException e) {
                failedOpportunityIds.add(opp.Id);
                // In production you would likely log this to a custom log object
                // or platform event instead of debug.
                System.debug(LoggingLevel.ERROR,
                    'FollowUpTaskService: failed to create task for Opportunity ' +
                    opp.Id + ' – ' + e.getMessage());
            }
        }

        return failedOpportunityIds;
    }
}
