trigger OpportunityTrigger on Opportunity (after insert, after update) {
    // Only run after insert/update when StageName or Amount changes (or on insert).
    // Per requirements, we enqueue one @future call per qualifying Opportunity.
    // NOTE: A batch of 200 will enqueue 200 future calls, exceeding the 50-call/transaction limit.
    // In production we would deduplicate AccountIds and pass a Set<Id> to a single future call.
    if (Trigger.isAfter && (Trigger.isInsert || Trigger.isUpdate)) {
        for (Opportunity opp : Trigger.new) {
            if (opp.AccountId == null) continue;

            if (Trigger.isInsert) {
                AccountRatingService.recalculate(opp.AccountId);
            } else {
                Opportunity oldOpp = Trigger.oldMap.get(opp.Id);
                if (opp.StageName != oldOpp.StageName || opp.Amount != oldOpp.Amount) {
                    AccountRatingService.recalculate(opp.AccountId);
                }
            }
        }
    }
}
