public with sharing class AccountRatingService {

    /**
     * Recalculates the Account.Rating based on its open Opportunities.
     * Called asynchronously via @future so Opportunity DML stays fast.
     *
     * Rating rules:
     *  - Hot   : ≥1 open Opportunity with Amount ≥ 100,000
     *  - Warm  : open Opportunities exist, but none ≥ 100,000
     *  - Cold  : no open Opportunities
     *
     * @param accountId Account to recalculate. Null is a no-op.
     */
    @future
    public static void recalculate(Id accountId) {
        if (accountId == null) return;

        // Fetch open opportunities for this account.
        // IsClosed = false is the standard "open" flag.
        List<Opportunity> openOpps = [
            SELECT Amount
            FROM Opportunity
            WHERE AccountId = :accountId
              AND IsClosed = false
        ];

        String newRating;
        if (openOpps.isEmpty()) {
            newRating = 'Cold';
        } else {
            Boolean hasLargeOpp = false;
            for (Opportunity o : openOpps) {
                if (o.Amount != null && o.Amount >= 100000) {
                    hasLargeOpp = true;
                    break;
                }
            }
            newRating = hasLargeOpp ? 'Hot' : 'Warm';
        }

        // Update only the Rating field to minimise locking/contention.
        Account acc = new Account(Id = accountId, Rating = newRating);
        try {
            update acc;
        } catch (DmlException e) {
            // Swallow & log; the job is idempotent and will self-heal on next change.
            System.debug(LoggingLevel.ERROR,
                'AccountRatingService failed to update Account ' + accountId + ': ' + e.getMessage());
        }
    }
}
