public with sharing class LineItemDiscountHandler {

    /**
     * Applies standard product discounts to new opportunity line items that don't
     * already have a discount value. Bulk-safe for up to 200 lines per transaction.
     *
     * @param newLines list of OpportunityLineItem records being inserted
     */
    public static void handleBeforeInsert(List<OpportunityLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        // Collect unique Product2Ids for lines needing a discount
        Set<Id> productIdsNeedingDiscount = new Set<Id>();
        for (OpportunityLineItem line : newLines) {
            // Only process lines where Discount is null (not 0, not populated)
            // and Product2Id is populated
            if (line.Discount == null && line.Product2Id != null) {
                productIdsNeedingDiscount.add(line.Product2Id);
            }
        }

        if (productIdsNeedingDiscount.isEmpty()) {
            return;
        }

        // Cache standard discounts per product to avoid duplicate SOQL calls
        // PricingRules.standardDiscountFor queries Product2 each call; with 200 lines
        // this would hit the 100 SOQL limit. Caching keeps us at 1 query per unique product.
        Map<Id, Decimal> standardDiscountByProduct = new Map<Id, Decimal>();
        for (Id productId : productIdsNeedingDiscount) {
            standardDiscountByProduct.put(productId, PricingRules.standardDiscountFor(productId));
        }

        // Apply cached discounts
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                Decimal stdDiscount = standardDiscountByProduct.get(line.Product2Id);
                if (stdDiscount != null) {
                    line.Discount = stdDiscount;
                }
            }
        }
    }
}
