public with sharing class LeadContactMatcher {

    /**
     * Matches leads to contacts by email address.
     *
     * @param leads    Leads to match. Order is preserved in the result.
     * @param contacts Contacts to search. First match in this list wins.
     * @return List of Contact Ids aligned with the leads list; null where no match.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> matchedContactIds = new List<Id>(leads.size());

        for (Lead lead : leads) {
            Id matchedId = null;
            String leadEmail = normalizeEmail(lead.Email);

            if (leadEmail != null) {
                for (Contact contact : contacts) {
                    String contactEmail = normalizeEmail(contact.Email);
                    if (contactEmail != null && contactEmail == leadEmail) {
                        matchedId = contact.Id;
                        break; // first match in contacts order wins
                    }
                }
            }
            matchedContactIds.add(matchedId);
        }

        return matchedContactIds;
    }

    /**
     * Normalizes an email for comparison: trims whitespace and lower-cases.
     * Returns null if the input is null or blank after trimming.
     */
    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }
        String trimmed = email.trim();
        return trimmed.isEmpty() ? null : trimmed.toLowerCase();
    }
}
