public with sharing class CaseSurveyJob implements Queueable {
    private final Id caseId;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    public void execute(QueueableContext context) {
        // Query the case with ContactId to avoid extra query in trigger
        Case c = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id = :caseId
            LIMIT 1
        ];

        // No contact = no survey task
        if (c.ContactId == null) {
            return;
        }

        Task surveyTask = new Task(
            WhatId = c.Id,
            WhoId = c.ContactId,
            Subject = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );

        try {
            insert surveyTask;
        } catch (DmlException e) {
            // Log and swallow - this job is fire-and-forget; other cases unaffected
            System.debug(LoggingLevel.ERROR, 'Failed to create CSAT survey task for Case ' + c.Id + ': ' + e.getMessage());
        }
    }
}
