public with sharing class RenewalReminderService {

    /**
     * Sends renewal reminder emails to opportunity owners.
     *
     * @param opportunityIds List of opportunity IDs (up to 200) whose renewal is due.
     * @return Number of emails sent successfully.
     *
     * DESIGN NOTE (why the requested approach is problematic):
     * 1. Calling Messaging.sendEmail inside a loop burns through the daily email limit
     *    (5,000 external emails/day for most editions) with separate API calls.
     * 2. Each sendEmail call consumes CPU time and adds governor-limit risk.
     * 3. The platform is optimized for bulk sends: collect all SingleEmailMessage
     *    instances in a list and call sendEmail ONCE. The method still returns a
     *    SendEmailResult[] where you can inspect per-email success/failure.
     * 4. If you truly need isolation, catch exceptions per sendEmail call, but the
     *    bulk pattern is strongly preferred and avoids the 10-email-per-transaction
     *    limit that existed in very old API versions (no longer enforced, but the
     *    bulk pattern remains best practice).
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Fetch opportunities with owner information in one query.
        // OwnerId can be User or Queue; we only email Users.
        List<Opportunity> opps = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        Integer sentCount = 0;

        for (Opportunity opp : opps) {
            // Skip if owner is a Queue, null, or not a User.
            if (opp.OwnerId == null || !opp.OwnerId.getSObjectType().equals(User.sObjectType)) {
                continue;
            }

            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opp.Name);
            email.setPlainTextBody(
                'The renewal for opportunity "' + opp.Name +
                '" is due on ' + opp.CloseDate.format() + '.'
            );

            // Per requirements: one sendEmail call per opportunity.
            // In production, collect all emails and call sendEmail once.
            try {
                Messaging.SendEmailResult[] results = Messaging.sendEmail(
                    new Messaging.SingleEmailMessage[] { email }
                );
                if (results != null && !results.isEmpty() && results[0].isSuccess()) {
                    sentCount++;
                }
            } catch (Exception e) {
                // Swallow and continue so other emails still go out.
                System.debug(LoggingLevel.ERROR,
                    'RenewalReminderService: failed to send email for Opportunity ' +
                    opp.Id + ' – ' + e.getMessage()
                );
            }
        }

        return sentCount;
    }
}
