    @api recordId;

    casesLinkUrl;

    connectedCallback() {
        this.generateCasesLink();
    }

    generateCasesLink() {
        const pageReference = {
            type: 'standard__objectPage',
            attributes: {
                objectApiName: 'Case',
                actionName: 'list'
            },
            state: {
                filterName: 'My_Open_Cases'
            }
        };

        this[NavigationMixin.GenerateUrl](pageReference)
            .then(url => {
                this.casesLinkUrl = url;
            })
            .catch(error => {
                console.error('Failed to generate cases list view URL:', error);
            });
    }

    handleButtonClick(event) {
        const action = event.currentTarget.dataset.action;

        switch (action) {
            case 'new-contact':
                this.navigateToNewContact();
                break;
            case 'contacts':
                this.navigateToContacts();
                break;
            case 'edit':
                this.navigateToEdit();
                break;
            default:
                break;
        }
    }

    navigateToNewContact() {
        const defaultFieldValues = encodeDefaultFieldValues({
            AccountId: this.recordId
        });

        this[NavigationMixin.Navigate]({
            type: 'standard__objectPage',
            attributes: {
                objectApiName: 'Contact',
                actionName: 'new'
            },
            state: {
                defaultFieldValues
            }
        });
    }

    navigateToContacts() {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordRelationshipPage',
            attributes: {
                recordId: this.recordId,
                objectApiName: 'Account',
                relationshipApiName: 'Contacts',
                actionName: 'view'
            }
        });
    }

    navigateToEdit() {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId: this.recordId,
                objectApiName: 'Account',
                actionName: 'edit'
            }
        });
    }
}
