import { LightningElement, track } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    @track waiting;
    @track longestWaitMinutes;
    @track error;

    // Track if a request is currently in flight
    requestInFlight = false;

    // Track the polling interval ID
    refreshIntervalId = null;

    // Track component connection state
    isConnected = false;

    // Store bound handler for proper removal
    boundVisibilityHandler = null;

    connectedCallback() {
        this.isConnected = true;
        this.boundVisibilityHandler = this.handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this.boundVisibilityHandler);

        this.loadStats();
        this.startPolling();
    }

    disconnectedCallback() {
        this.isConnected = false;
        this.stopPolling();

        if (this.boundVisibilityHandler) {
            document.removeEventListener('visibilitychange', this.boundVisibilityHandler);
            this.boundVisibilityHandler = null;
        }
    }

    handleVisibilityChange() {
        if (!this.isConnected) {
            return;
        }

        if (document.visibilityState === 'visible') {
            // Page became visible: load immediately and resume polling
            this.loadStats();
            this.startPolling();
        } else if (document.visibilityState === 'hidden') {
            // Page hidden: stop polling to avoid background requests
            this.stopPolling();
        }
    }

    startPolling() {
        this.stopPolling(); // Ensure no duplicate intervals

        this.refreshIntervalId = setInterval(() => {
            if (this.isConnected && document.visibilityState === 'visible') {
                this.loadStats();
            }
        }, 60000); // 60 seconds
    }

    stopPolling() {
        if (this.refreshIntervalId) {
            clearInterval(this.refreshIntervalId);
            this.refreshIntervalId = null;
        }
    }

    async loadStats() {
        // Skip if a request is already in flight
        if (this.requestInFlight) {
            return;
        }

        // Do not request while the tab is hidden
        if (document.visibilityState === 'hidden') {
            return;
        }

        this.requestInFlight = true;

        try {
            const result = await getQueueStats();
            this.waiting = result.waiting;
            this.longestWaitMinutes = result.longestWaitMinutes;
            this.error = null; // Clear any previous error on success
        } catch (error) {
            this.error = error.body?.message || 'An error occurred';
            // Keep previous stats visible; continue polling
        } finally {
            this.requestInFlight = false;
        }
    }
}
