public with sharing class EmployerService {
    /**
     * Sets the current employer for each contact using NPSP's standard primary affiliation mechanism.
     * NPSP triggers automatically manage affiliation records: creating/updating the new primary
     * affiliation as Current, and ending the previous primary affiliation as Former with today's end date.
     *
     * @param employerByContactId Map of Contact Id to Organization Account Id (employer).
     *                            Null or empty map does nothing.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // Fetch current primary affiliation for each contact (1 SOQL)
        List<Contact> contacts = [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ];

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact c : contacts) {
            Id newEmployerId = employerByContactId.get(c.Id);
            // Only update if employer changed (skips null employerId and no-op cases)
            if (newEmployerId != null && newEmployerId != c.npsp__Primary_Affiliation__c) {
                c.npsp__Primary_Affiliation__c = newEmployerId;
                contactsToUpdate.add(c);
            }
        }

        // Update contacts; NPSP TDTM triggers handle affiliation create/update/end-date logic (1 DML)
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
