public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage one NPSP Data Import record per gift
        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Contact1_Firstname__c = gift.firstName;
            di.npsp__Contact1_Lastname__c = gift.lastName;
            di.npsp__Contact1_Personal_Email__c = gift.email;
            di.npsp__Donation_Amount__c = gift.amount;
            di.npsp__Donation_Date__c = gift.giftDate;
            di.npsp__Donation_Donor__c = 'Contact1';
            dataImports.add(di);
        }

        // Insert all staged records in a single DML
        insert dataImports;

        // Collect IDs for the synchronous import call
        List<Id> dataImportIds = new List<Id>();
        for (npsp__DataImport__c di : dataImports) {
            dataImportIds.add(di.Id);
        }

        // Process synchronously using NPSP's Apex API; this honors the org's
        // Data Import settings (npsp__Data_Import_Settings__c) for contact matching,
        // household creation, and donation processing rules.
        npsp.DataImportService.importData(dataImportIds);

        // Retrieve the processed records with NPSP's result fields
        List<npsp__DataImport__c> processedImports = [
            SELECT Id,
                   npsp__Status__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c,
                   npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :dataImportIds
        ];

        Map<Id, npsp__DataImport__c> importMap = new Map<Id, npsp__DataImport__c>(processedImports);

        // Build results in the original input order
        for (npsp__DataImport__c di : dataImports) {
            npsp__DataImport__c processed = importMap.get(di.Id);
            ImportResult result = new ImportResult();

            if (processed != null && processed.npsp__Status__c == 'Imported') {
                result.success = true;
                result.contactId = processed.npsp__Contact1Imported__c;
                result.opportunityId = processed.npsp__DonationImported__c;
            } else {
                result.success = false;
                result.errorMessage = (processed != null && processed.npsp__FailureInformation__c != null)
                    ? processed.npsp__FailureInformation__c
                    : 'Import failed with no error details';
            }

            results.add(result);
        }

        return results;
    }
}
