public class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replaces all GAU allocations on the given opportunity with new percentage-based allocations.
     * Percentages are stored on npsp__Percent__c so that NPSP automatically recalculates amounts
     * when the opportunity amount changes.
     *
     * @param opportunityId     The Opportunity to allocate.
     * @param percentByGauId    Map of GAU Id → percentage (e.g. 60 = 60%). Total may be ≤ 100.
     * @return                  The inserted allocation records.
     * @throws AllocationException if validation fails.
     */
    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // ---------- Validation ----------
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('Percent-by-GAU map cannot be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Decimal pct : percentByGauId.values()) {
            if (pct == null || pct <= 0) {
                throw new AllocationException('All percentages must be greater than zero.');
            }
            totalPercent += pct;
        }

        if (totalPercent > 100) {
            throw new AllocationException('Percentages add up to ' + totalPercent
                + '%, which exceeds the maximum of 100%.');
        }

        Set<Id> gauIds = percentByGauId.keySet();
        List<npsp__General_Accounting_Unit__c> gaus = [
            SELECT Id, Name, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :gauIds
        ];

        if (gaus.size() != gauIds.size()) {
            throw new AllocationException('One or more GAU records not found.');
        }

        for (npsp__General_Accounting_Unit__c gau : gaus) {
            if (!gau.npsp__Active__c) {
                throw new AllocationException('GAU "' + gau.Name + '" is inactive.');
            }
        }

        // ---------- Replace allocations ----------
        // Delete existing allocations for this opportunity
        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existing.isEmpty()) {
            delete existing;
        }

        // Create new percentage-based allocations
        List<npsp__Allocation__c> toInsert = new List<npsp__Allocation__c>();
        for (Id gauId : gauIds) {
            toInsert.add(new npsp__Allocation__c(
                npsp__Opportunity__c            = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c                = percentByGauId.get(gauId)
                // npsp__Amount__c is deliberately omitted – NPSP calculates it from Percent
            ));
        }

        if (!toInsert.isEmpty()) {
            insert toInsert;
        }

        return toInsert;
    }
}
