public with sharing class FamilyService {

    /**
     * Creates NPSP Relationship records linking each child to their parent.
     * Only the forward relationship (Child → Parent, Type = 'Parent') is inserted;
     * NPSP's reciprocal trigger automatically creates the reverse record
     * (Parent → Child, Type = Son/Daughter/Child based on the child's gender).
     *
     * @param parentIdByChildId  Map of Child Contact Id → Parent Contact Id.
     *                           Null or empty map does nothing.
     *                           Pairs where any relationship already exists
     *                           in either direction are skipped.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // -----------------------------------------------------------------
        // 1. Collect every Contact Id that participates in the import.
        // -----------------------------------------------------------------
        Set<Id> allContactIds = new Set<Id>();
        allContactIds.addAll(parentIdByChildId.keySet());
        allContactIds.addAll(parentIdByChildId.values());

        // -----------------------------------------------------------------
        // 2. Single SOQL query: fetch every existing relationship where both
        //    contacts are in our working set.  This lets us detect pre-existing
        //    links in either direction without additional queries.
        // -----------------------------------------------------------------
        List<npe4__Relationship__c> existingRels = [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
              AND npe4__RelatedContact__c IN :allContactIds
        ];

        // -----------------------------------------------------------------
        // 3. Build an in-memory set of "blocked" pairs (both directions) so
        //    we can skip any input pair that already has a relationship.
        // -----------------------------------------------------------------
        Set<String> blockedPairs = new Set<String>();
        for (npe4__Relationship__c rel : existingRels) {
            blockedPairs.add(rel.npe4__Contact__c + ':' + rel.npe4__RelatedContact__c);
            blockedPairs.add(rel.npe4__RelatedContact__c + ':' + rel.npe4__Contact__c);
        }

        // -----------------------------------------------------------------
        // 4. Prepare new Relationship records for pairs that are not blocked.
        // -----------------------------------------------------------------
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (parentId == null) {
                continue; // defensive: skip null parent
            }

            String forwardKey  = childId + ':' + parentId;
            String reverseKey  = parentId + ':' + childId;

            if (blockedPairs.contains(forwardKey) || blockedPairs.contains(reverseKey)) {
                continue; // relationship already exists in at least one direction
            }

            npe4__Relationship__c rel = new npe4__Relationship__c();
            rel.npe4__Contact__c               = childId;   // the child
            rel.npe4__RelatedContact__c        = parentId;  // the parent
            rel.npe4__Type__c                  = 'Parent';  // per Relationship Lookup setting
            rel.npe4__Status__c                = 'Current'; // required by specification
            // npe4__ReciprocalRelationship__c is populated automatically by NPSP trigger
            toInsert.add(rel);

            // Mark both directions as blocked so a later reverse pair in the same
            // batch is also skipped (idempotency within a single execution).
            blockedPairs.add(forwardKey);
            blockedPairs.add(reverseKey);
        }

        // -----------------------------------------------------------------
        // 5. Single DML statement: insert all new forward relationships.
        // -----------------------------------------------------------------
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
