global class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        List<Opportunity> newOpps = (List<Opportunity>) newlist;
        List<Opportunity> oldOpps = (List<Opportunity>) oldlist;

        Map<Id, Opportunity> oldOppMap = new Map<Id, Opportunity>(oldOpps);
        Set<Id> qualifyingOppIds = new Set<Id>();

        for (Integer i = 0; i < newOpps.size(); i++) {
            Opportunity newOpp = newOpps[i];
            Opportunity oldOpp = oldOppMap.get(newOpp.Id);

            Boolean isClosedWon = newOpp.StageName == 'Closed Won';
            Boolean isMajorGift = newOpp.Amount != null && newOpp.Amount >= 5000;

            if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
                if (isClosedWon && isMajorGift) {
                    qualifyingOppIds.add(newOpp.Id);
                }
            } else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
                Boolean wasClosedWon = oldOpp != null && oldOpp.StageName == 'Closed Won';
                Boolean wasMajorGift = oldOpp != null && oldOpp.Amount != null && oldOpp.Amount >= 5000;

                if (isClosedWon && isMajorGift && (!wasClosedWon || !wasMajorGift)) {
                    qualifyingOppIds.add(newOpp.Id);
                }
            }
        }

        if (qualifyingOppIds.isEmpty()) {
            return new npsp.TDTM_Runnable.DmlWrapper();
        }

        // One SOQL query to find opportunities that already have the follow-up task
        Set<Id> oppIdsWithExistingTask = new Set<Id>();
        for (Task existingTask : [
            SELECT WhatId
            FROM Task
            WHERE WhatId IN :qualifyingOppIds
              AND Subject = 'Major gift thank-you call'
        ]) {
            oppIdsWithExistingTask.add(existingTask.WhatId);
        }

        List<Task> tasksToInsert = new List<Task>();
        for (Opportunity opp : newOpps) {
            if (qualifyingOppIds.contains(opp.Id) && !oppIdsWithExistingTask.contains(opp.Id)) {
                Task t = new Task();
                t.Subject = 'Major gift thank-you call';
                t.Priority = 'High';
                t.Status = 'Not Started';
                t.WhatId = opp.Id;
                t.WhoId = opp.npsp__Primary_Contact__c;
                t.OwnerId = opp.OwnerId;
                t.ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null;
                tasksToInsert.add(t);
            }
        }

        // One DML statement via the returned DmlWrapper
        return new npsp.TDTM_Runnable.DmlWrapper(
            new List<SObject>(),          // toInsert
            tasksToInsert,                // toUpdate (Task is inserted as "update" in TDTM parlance)
            new List<SObject>()           // toDelete
        );
    }
}
