public inherited sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        checkForDuplicateEmails(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        checkForDuplicateEmails(triggerNew, triggerOld);
    }

    private void checkForDuplicateEmails(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> contactsToCheck = new List<Contact>();
        Map<Id, Contact> oldContactMap = new Map<Id, Contact>();

        if (triggerOld != null) {
            for (SObject obj : triggerOld) {
                oldContactMap.put(obj.Id, (Contact) obj);
            }
        }

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact newContact = (Contact) triggerNew[i];
            if (newContact.AccountId == null || newContact.Email == null) {
                continue;
            }

            if (triggerOld != null) {
                Contact oldContact = oldContactMap.get(newContact.Id);
                if (oldContact != null &&
                    newContact.Email == oldContact.Email &&
                    newContact.AccountId == oldContact.AccountId) {
                    continue;
                }
            }

            contactsToCheck.add(newContact);
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        for (Contact c : contactsToCheck) {
            accountIds.add(c.AccountId);
            emails.add(c.Email.toLowerCase());
        }

        Map<String, Id> existingEmailToContactId = new Map<String, Id>();
        for (Contact existing : [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                  AND Email IN :emails
        ]) {
            String key = existing.AccountId + ':' + existing.Email.toLowerCase();
            if (!existingEmailToContactId.containsKey(key)) {
                existingEmailToContactId.put(key, existing.Id);
            }
        }

        Map<String, Contact> firstSeenInBatch = new Map<String, Contact>();

        for (Contact c : contactsToCheck) {
            String key = c.AccountId + ':' + c.Email.toLowerCase();

            if (existingEmailToContactId.containsKey(key)) {
                c.addError(ERROR_MESSAGE);
                continue;
            }

            Contact firstInBatch = firstSeenInBatch.get(key);
            if (firstInBatch != null) {
                c.addError(ERROR_MESSAGE);
            } else {
                firstSeenInBatch.put(key, c);
            }
        }
    }
}
