public with sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        for (SObject record : triggerNew) {
            Lead lead = (Lead) record;

            // Email: trim whitespace and lower-case; null stays null
            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }

            // Company: trim whitespace
            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }

            // LeadSource: set to 'Web' when blank; keep existing value
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }
        }
    }
}
